# ====== 工具函数 ======
def find(table, name):
    for k, v in table:
        if k.strip().startswith(name.strip()):
            return v
    raise KeyError(name)


def safe_div(a, b):
    if a is None or b is None or b == 0:
        return None
    return a / b


TOL = 1000.0  # 元级容差 (对 500 亿+ 级数据 = 万亿分之二, 舍入误差可接受)
TOL_OLD = 10000.0  # 旧准则期容差稍宽 (旧准则期数据在 2005 年报中可能有微小舍入)


# ====== 勾稽自洽校验 (分准则期) ======
def verify():
    errors = []
    for i, y in enumerate(YEARS):
        is_old_gaap = y <= 2005  # 2000-2005 旧准则期
        tol = TOL_OLD if is_old_gaap else TOL

        # ---- 损益: 归母 + 少数 = 净利润 ----
        parent = find(利润表, "  归母净利润")[i]
        minor = find(利润表, "  少数股东损益")[i]
        np = find(利润表, "五、净利润")[i]
        if parent is not None and minor is not None and np is not None:
            if abs(parent + minor - np) > tol:
                errors.append(f"{y} 损益: 归母{parent} + 少数{minor} ≠ 净利润{np} (差 {parent+minor-np:.2f})")

        # ---- 损益: 净利润 = 利润总额 - 所得税 ----
        tax = find(利润表, "减:所得税费用")[i]
        pbt = find(利润表, "四、利润总额")[i]
        if pbt is not None and tax is not None and np is not None:
            if abs(pbt - tax - np) > tol:
                errors.append(f"{y} 损益: 利润总额{pbt} - 所得税{tax} ≠ 净利润{np} (差 {pbt-tax-np:.2f})")

        # ---- 损益: 利润总额 = 营业利润 + 营业外收入 - 营业外支出 (2006 起新准则) ----
        # 旧准则: 利润总额 = 营业利润 + 投资收益 + 补贴收入 + 营业外收入 - 营业外支出
        op = find(利润表, "三、营业利润")[i]
        n_inc = find(利润表, "加:营业外收入")[i]
        n_exp = find(利润表, "减:营业外支出")[i]
        if op is not None and pbt is not None:
            if is_old_gaap:
                inv_inc = find(利润表, "加:投资收益")[i] or 0
                sub_inc = find(利润表, "  加:补贴收入(旧准则期)")[i] or 0
                pbt_calc = op + inv_inc + sub_inc + n_inc - n_exp
            else:
                pbt_calc = op + n_inc - n_exp
            if abs(pbt_calc - pbt) > tol:
                errors.append(f"{y} 损益: 利润总额重算{pbt_calc:.2f} ≠ 报表{pbt} (差 {pbt_calc-pbt:.2f})")

        # ---- 资产负债: 流动+非流动 = 总资产 ----
        tca = find(资产负债表, "流动资产合计")[i]
        tnca = find(资产负债表, "非流动资产合计")[i]
        ta = find(资产负债表, "资产总计")[i]
        if tca is not None and tnca is not None and ta is not None:
            if abs(tca + tnca - ta) > tol:
                errors.append(f"{y} 资产负债: 流动{tca} + 非流动{tnca} ≠ 总资产{ta} (差 {tca+tnca-ta:.2f})")

        # ---- 资产负债: 流动+非流动负债 = 总负债 (2018 无非流动负债→None 视为 0) ----
        tcl = find(资产负债表, "流动负债合计")[i]
        tncl_raw = find(资产负债表, "非流动负债合计")[i]
        tncl = tncl_raw or 0
        tl = find(资产负债表, "负债合计")[i]
        if tcl is not None and tl is not None:
            if abs(tcl + tncl - tl) > tol:
                errors.append(f"{y} 资产负债: 流动负债{tcl} + 非流动负债{tncl} ≠ 负债合计{tl}")

        # ---- 资产负债: 总资产 = 总负债 + 总权益 ----
        eq = find(资产负债表, "所有者权益合计")[i]
        if tl is not None and eq is not None and ta is not None:
            if abs(tl + eq - ta) > tol:
                errors.append(f"{y} 资产负债: 负债{tl} + 权益{eq} ≠ 总资产{ta} (差 {tl+eq-ta:.2f})")

        # ---- 资产负债: 归母 + 少数 = 总权益 ----
        parent_eq = find(资产负债表, "归母权益合计")[i]
        minor_eq = find(资产负债表, "少数股东权益")[i]
        if parent_eq is not None and minor_eq is not None and eq is not None:
            if abs(parent_eq + minor_eq - eq) > tol:
                errors.append(f"{y} 资产负债: 归母权益{parent_eq} + 少数{minor_eq} ≠ 总权益{eq} (差 {parent_eq+minor_eq-eq:.2f})")

        # ---- 现金流: 经营 + 投资 + 筹资 + 汇率 = 净增加 (仅当所有值都有时) ----
        ocf = find(现金流量表, "经营活动产生的现金流量净额")[i]
        icf = find(现金流量表, "投资活动产生的现金流量净额")[i]
        fcf = find(现金流量表, "筹资活动产生的现金流量净额")[i]
        fx = find(现金流量表, "汇率变动对现金及现金等价物的影响")[i]
        netchg = find(现金流量表, "现金及现金等价物净增加额")[i]
        if all(v is not None for v in [ocf, icf, fcf, fx, netchg]):
            s = ocf + icf + fcf + fx
            if abs(s - netchg) > tol:
                errors.append(f"{y} 现金流: 经{ocf} + 投{icf} + 筹{fcf} + 汇{fx} = {s:.2f} ≠ 净增加{netchg} (差 {s-netchg:.2f})")

        # ---- 现金流: 期初 + 净增加 = 期末 ----
        beg = find(现金流量表, "期初现金及现金等价物余额")[i]
        end = find(现金流量表, "期末现金及现金等价物余额")[i]
        if all(v is not None for v in [beg, netchg, end]):
            if abs(beg + netchg - end) > tol:
                errors.append(f"{y} 现金流: 期初{beg} + 净增加{netchg} ≠ 期末{end}")

    # ---- 现金流: 年初 = 上年末 ----
    # 2000-2005 旧准则期现金流数据部分缺失·跳过
    # 2005→2006 是 CAS 2006 准则切换点·2006 期初经新准则重述·与 2005 旧准则期末不完全一致(差 374 万)·跳过
    beg_arr = find(现金流量表, "期初现金及现金等价物余额")
    end_arr = find(现金流量表, "期末现金及现金等价物余额")
    for i in range(1, len(YEARS)):
        if YEARS[i] <= 2006:
            continue  # 跳过旧准则期 + 2005→2006 准则切换点
        if end_arr[i-1] is None or beg_arr[i] is None:
            continue
        if abs(end_arr[i-1] - beg_arr[i]) > TOL:
            errors.append(f"{YEARS[i]} 现金连续性: 上年末{end_arr[i-1]} ≠ 本年初{beg_arr[i]}")

    return errors


# ====== 派生比率 ======
def build_ratios():
    rev = find(利润表, "  营业收入")
    tor = find(利润表, "一、营业总收入")
    cos = find(利润表, "  营业成本")
    npr = find(利润表, "五、净利润")
    parent = find(利润表, "  归母净利润")
    tax_add = find(利润表, "  税金及附加(消费税等)")
    snd = find(利润表, "  销售费用")
    adm = find(利润表, "  管理费用")
    rd = find(利润表, "  研发费用")

    ta = find(资产负债表, "资产总计")
    tl = find(资产负债表, "负债合计")
    parent_eq = find(资产负债表, "归母权益合计")
    ar = find(资产负债表, "应收账款")
    inv = find(资产负债表, "存货")
    cl = find(资产负债表, "合同负债/预收款项")

    ocf = find(现金流量表, "经营活动产生的现金流量净额")
    sale_cash = find(现金流量表, "销售商品、提供劳务收到的现金")
    capex = find(现金流量表, "购建固定资产等支付的现金(capex)")

    n = len(YEARS)
    rows = [
        ("毛利率 (营业总收入-营业成本)/营业总收入", [safe_div(tor[i] - cos[i], tor[i]) if tor[i] is not None and cos[i] is not None else None for i in range(n)]),
        ("毛利率 (营业收入-营业成本)/营业收入",     [safe_div(rev[i] - cos[i], rev[i]) if rev[i] is not None and cos[i] is not None else None for i in range(n)]),
        ("净利率 归母净利/营业总收入",              [safe_div(parent[i], tor[i]) for i in range(n)]),
        ("税金及附加/营业收入 (消费税负担率)",      [safe_div(tax_add[i], rev[i]) for i in range(n)]),
        ("销售费用率 销售费用/营业收入",            [safe_div(snd[i], rev[i]) for i in range(n)]),
        ("管理费用率 管理费用/营业收入",            [safe_div(adm[i], rev[i]) for i in range(n)]),
        ("研发费用率 研发费用/营业收入",            [safe_div(rd[i], rev[i]) if rd[i] is not None else None for i in range(n)]),
        ("ROE(期末) 归母净利/期末归母权益",         [safe_div(parent[i], parent_eq[i]) for i in range(n)]),
        ("ROE(年均) 归母净利/年均归母权益",         [None] + [safe_div(parent[i], (parent_eq[i]+parent_eq[i-1])/2) if parent_eq[i] and parent_eq[i-1] else None for i in range(1, n)]),
        ("现金含量 经营现金流/净利润",              [safe_div(ocf[i], npr[i]) for i in range(n)]),
        ("收现比 销售收现/营业收入",                [safe_div(sale_cash[i], rev[i]) if sale_cash[i] is not None else None for i in range(n)]),
        ("Capex/净利润 (维持利润所需资本比)",       [safe_div(-capex[i], npr[i]) if capex[i] is not None else None for i in range(n)]),
        ("应收/营业收入",                           [safe_div(ar[i], rev[i]) if ar[i] is not None else 0.0 for i in range(n)]),
        ("存货/营业收入",                           [safe_div(inv[i], rev[i]) for i in range(n)]),
        ("合同负债/营业收入 (蓄水池占比)",          [safe_div(cl[i], rev[i]) for i in range(n)]),
        ("资产负债率 总负债/总资产",                [safe_div(tl[i], ta[i]) for i in range(n)]),
    ]
    return rows


# ====== 写 CSV ======
def write_csv(filename, rows, unit_note=""):
    path = os.path.join(OUT, filename)
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        if unit_note:
            w.writerow([f"# {unit_note}"])
        w.writerow(["科目"] + [str(y) for y in YEARS])
        for name, vals in rows:
            row = [name]
            for v in vals:
                if v is None:
                    row.append("")
                elif isinstance(v, float):
                    if abs(v) < 1 and v != 0:
                        row.append(f"{v:.6f}")
                    else:
                        row.append(f"{v:.2f}")
                else:
                    row.append(str(v))
            w.writerow(row)
    print(f"  ✅ {filename}  ({len(rows)} 行)")


# ====== main ======
if __name__ == "__main__":
    print("=" * 60)
    print("贵州茅台 财务数据构建 · 从一手年报 PDF 解析 (26 年 2000-2025)")
    print("=" * 60)
    print(f"覆盖年份: {YEARS[0]}-{YEARS[-1]} · 共 {len(YEARS)} 年")
    print(f"  阶段 1 旧准则 (2000-2005 · 6 年)")
    print(f"  阶段 2 新准则 CAS 早期 (2006-2015 · 10 年)")
    print(f"  阶段 3 新准则 CAS 后期 (2016-2025 · 10 年)")
    print()

    print("勾稽自洽校验 (分准则期)...")
    errs = verify()
    if errs:
        print(f"❌ 校验失败 ({len(errs)} 条), 不写出 CSV:")
        for e in errs:
            print(f"   {e}")
        raise SystemExit(1)
    print(f"✅ 三表勾稽全部通过\n")

    print("写出 CSV:")
    write_csv("利润表.csv", 利润表, "单位: 人民币元, 26 年 2000-2025, 来源: 一手年报 PDF")
    write_csv("资产负债表.csv", 资产负债表, "单位: 人民币元, 资产负债权益全部正数, 库存股按正数存储(计算权益时减), 26 年 2000-2025")
    write_csv("现金流量表.csv", 现金流量表, "单位: 人民币元, 流出/减项=负数, 净额/汇率按报表符号, 26 年 2000-2025")
    write_csv("财务比率.csv", build_ratios(), "派生比率: 从一手三表计算, 比率为小数(如 0.9153 = 91.53%), 26 年 2000-2025")
    write_csv("分部营收.csv", 分部营收, "单位: 人民币百万元 (RMB million), 来源: 年报第三节 MD&A; 2000-2019 待补下次会话")
    print("\n🎊 全部写出完成 · 26 年数据源: report/贵州茅台/{2001,2003,2005,2007,2009,2011,2013,2015,2016,2018,2019,2021,2023,2024,2025}.pdf")
